-- 邮件模板表
CREATE TABLE IF NOT EXISTS `sys_email_template` (
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
    `template_code` varchar(50) NOT NULL COMMENT '模板编码',
    `template_name` varchar(100) NOT NULL COMMENT '模板名称',
    `subject` varchar(200) NOT NULL COMMENT '邮件主题',
    `content` text NOT NULL COMMENT '模板内容',
    `remark` varchar(500) DEFAULT NULL COMMENT '模板说明',
    `status` int DEFAULT 1 COMMENT '状态：0=禁用 1=启用',
    `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
    `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_template_code` (`template_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='邮件模板表';

-- 插入默认模板（右上角带复制按钮）
INSERT INTO `sys_email_template` (`template_code`, `template_name`, `subject`, `content`, `remark`, `status`) VALUES
('verify_code', '邮箱验证码模板', '您有一封来自 ${siteName} 的回执！', 
'<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>邮箱验证码</title>\n    <style type=\"text/css\">\n        .qmbox h1,.qmbox h2,.qmbox h3{color:#00785a;}\n        .qmbox p{padding:0;margin:0;color:#333;font-size:16px;}\n        .qmbox hr{background-color:#d9d9d9;border:none;height:1px;}\n        .qmbox .eo-link{color:#0576b9;text-decoration:none;cursor:pointer;}\n        .qmbox .eo-link:hover{color:#3498db;text-decoration:underline;}\n        .qmbox .p-intro{padding:30px;}\n        .qmbox .p-code{padding:0 30px 0 30px;}\n    </style>\n</head>\n<body>\n<div id=\"contentDiv\" style=\"position:relative;font-size:14px;height:auto;padding:15px 15px 10px 15px;z-index:1;zoom:1;line-height:1.7;\" class=\"body\">\n    <div id=\"qm_con_body\">\n        <div id=\"mailContentContainer\" class=\"qmbox qm_con_body_content\" style=\"opacity:1;\">\n            <div style=\"max-width:800px;padding-bottom:10px;margin:20px auto 0 auto;\">\n                <table cellpadding=\"0\" cellspacing=\"0\" style=\"background-color:#fff;border-collapse:collapse;border:1px solid #e5e5e5;box-shadow:0 10px 15px rgba(0,0,0,0.05);text-align:left;width:100%;font-size:14px;border-spacing:0;\">\n                    <tbody>\n                    <tr style=\"background-color:#f8f8f8;\">\n                        <td>\n                            <img style=\"padding:15px 0 15px 30px;width:50px\" src=\"${logoUrl}\" />\n                            <span>${siteName}</span>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td class=\"p-intro\">\n                            <h1 style=\"font-size:26px;font-weight:bold;\">验证您的邮箱地址</h1>\n                            <p style=\"line-height:1.75em;\">感谢您使用 ${siteName}. </p>\n                            <p style=\"line-height:1.75em;\">以下是您的邮箱验证码，请将它输入到 <span style=\"color:#409eff;\">${siteName}</span> 的邮箱验证码输入框中:</p>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td class=\"p-code\">\n                            <div style=\"position:relative;display:inline-block;margin:0 auto;\">\n                                <p id=\"verifyCode\" style=\"color:#253858;text-align:center;line-height:1.75em;background-color:#f2f2f2;min-width:200px;margin:0 auto;font-size:28px;border-radius:5px;border:1px solid #d9d9d9;font-weight:bold;padding-right:40px;\">${code}</p>\n                                <button onclick=\"copyCode()\" title=\"复制验证码\" style=\"position:absolute;right:4px;top:4px;background:#409eff;color:#fff;border:none;border-radius:3px;width:24px;height:24px;font-size:11px;cursor:pointer;line-height:24px;padding:0;\">复制</button>\n                            </div>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td class=\"p-intro\">\n                            <p style=\"line-height:1.75em;\">这一封邮件包括一些您的私密信息，请不要回复或转发它，以免带来不必要的信息泄露风险。 </p>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td class=\"p-intro\">\n                            <hr>\n                            <p style=\"text-align:center;line-height:1.75em;\">${siteName} - <a href=\"${siteUrl}\" style=\"text-decoration:none;color:#409eff\">${siteName}</a></p>\n                        </td>\n                    </tr>\n                    </tbody>\n                </table>\n            </div>\n            <style type=\"text/css\">.qmbox style,.qmbox script,.qmbox head,.qmbox link,.qmbox meta{display:none !important;}</style>\n        </div>\n    </div>\n    <style>#mailContentContainer .txt{height:auto;}</style>\n</div>\n<script>\nfunction copyCode(){var c=document.getElementById(\"verifyCode\").innerText;if(navigator.clipboard){navigator.clipboard.writeText(c).then(function(){alert(\"验证码已复制：\"+c);});}else{var t=document.createElement(\"textarea\");t.value=c;document.body.appendChild(t);t.select();document.execCommand(\"copy\");document.body.removeChild(t);alert(\"验证码已复制：\"+c);}}\n</script>\n</body>\n</html>',
'原版模板，验证码框右上角带复制按钮', 1);

SELECT id, template_code, template_name, status FROM sys_email_template;
